using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Text;

namespace codecrush.gstreamer.source_generator.tests;

public class ObjectManagerGeneratorTest
{
    private const string ObjectManagerPath = "/virtual/path/generated/GtkSharp/ObjectManager.cs";

    private const string Upstream =
        """
        // This file was generated by the Gtk# code generator.
        // Any changes made will be lost if regenerated.

        namespace GtkSharp.GstreamerSharp {

        	public class ObjectManager {

        		static bool initialized = false;
        		// Call this method from the appropriate module init function.
        		public static void Initialize ()
        		{
        			if (initialized)
        				return;

        			initialized = true;
        			GLib.GType.Register (Gst.App.AppSink.GType, typeof (Gst.App.AppSink));
        			GLib.GType.Register (Gst.App.AppSrc.GType, typeof (Gst.App.AppSrc));
        			GLib.GType.Register (Gst.WebRTC.WebRTCDTLSTransport.GType, typeof (Gst.WebRTC.WebRTCDTLSTransport));
        		}
        	}
        }
        """;

    [Fact]
    public void RegistersEveryTypeFromUpstreamInItsOrder()
    {
        var (driver, _) = Run(new InMemoryAdditionalText(ObjectManagerPath, Upstream));

        Assert.Empty(driver.GetRunResult().Diagnostics);

        var generated = Generated(driver);

        var sink = generated.IndexOf("Gst.App.AppSink", StringComparison.Ordinal);
        var src = generated.IndexOf("Gst.App.AppSrc", StringComparison.Ordinal);
        var webrtc = generated.IndexOf("Gst.WebRTC.WebRTCDTLSTransport", StringComparison.Ordinal);

        Assert.True(sink >= 0 && src > sink && webrtc > src, "registrations are not emitted in upstream order");
    }

    [Fact]
    public void RoutesEachRegistrationThroughTheGuard()
    {
        var (driver, _) = Run(new InMemoryAdditionalText(ObjectManagerPath, Upstream));

        var generated = Generated(driver);

        // The type is passed as a call, not a value: typeof() never runs a static
        // constructor, so the GType has to be read inside the guard.
        Assert.Contains(
            "GTypeRegistry.Register(static () => global::Gst.App.AppSink.GType, typeof(global::Gst.App.AppSink));",
            generated);

        // Nothing may call GLib.GType.Register unguarded - that is the shape that
        // took down every wrapper class on a runtime without every module.
        Assert.DoesNotContain("GLib.GType.Register", generated);
    }

    [Fact]
    public void KeepsUpstreamsInitialiseOnceBehaviour()
    {
        var (driver, _) = Run(new InMemoryAdditionalText(ObjectManagerPath, Upstream));

        var generated = Generated(driver);

        Assert.Contains("static bool initialized;", generated);
        Assert.Contains("if (initialized)", generated);

        // Set before the first registration: reading a GType runs that type's
        // static constructor, which calls back into Initialize().
        Assert.True(
            generated.IndexOf("initialized = true;", StringComparison.Ordinal)
            < generated.IndexOf("GTypeRegistry.Register", StringComparison.Ordinal));
    }

    [Fact]
    public void ReportsARegistrationItCannotRead()
    {
        // The list was rewritten in a form this generator does not know. That has
        // to fail the build: emitting a partial registry silently degrades every
        // wrapper of the missing types.
        var (driver, _) = Run(new InMemoryAdditionalText(
            ObjectManagerPath,
            """
            namespace GtkSharp.GstreamerSharp {
            	public class ObjectManager {
            		public static void Initialize () {
            			GLib.GType.Register (Gst.App.AppSink.GType, typeof (Gst.App.AppSrc));
            		}
            	}
            }
            """));

        var diagnostic = Assert.Single(driver.GetRunResult().Diagnostics);

        Assert.Equal("GSTOM001", diagnostic.Id);
        Assert.Equal(DiagnosticSeverity.Error, diagnostic.Severity);
        Assert.Contains("ObjectManager.cs", diagnostic.GetMessage());
        Assert.DoesNotContain("Gst.App.AppSrc", Generated(driver));
    }

    [Fact]
    public void ReportsAFileWithoutRegistrations()
    {
        var (driver, _) = Run(new InMemoryAdditionalText(
            ObjectManagerPath,
            "namespace GtkSharp.GstreamerSharp { public class ObjectManager { } }"));

        var diagnostic = Assert.Single(driver.GetRunResult().Diagnostics);

        Assert.Equal("GSTOM002", diagnostic.Id);
        Assert.Equal(DiagnosticSeverity.Error, diagnostic.Severity);
    }

    [Fact]
    public void ReportsMoreThanOneSource()
    {
        var (driver, _) = Run(
            new InMemoryAdditionalText(ObjectManagerPath, Upstream),
            new InMemoryAdditionalText("/virtual/path/other/ObjectManager.cs", Upstream));

        var diagnostic = Assert.Single(driver.GetRunResult().Diagnostics);

        Assert.Equal("GSTOM003", diagnostic.Id);
    }

    [Fact]
    public void IgnoresOtherAdditionalFiles()
    {
        var (driver, _) = Run(
            new InMemoryAdditionalText(
                "/virtual/path/gstreamer-sharp.dll.config",
                """<configuration><dllmap dll="gstreamer-1.0-0.dll" target="libgstreamer-1.0.so.0" os="linux"/></configuration>"""),
            new InMemoryAdditionalText("/virtual/path/Notes.cs", "class Notes { }"));

        Assert.Empty(driver.GetRunResult().Diagnostics);
        Assert.Empty(driver.GetRunResult().Results.Single().GeneratedSources);
    }

    [Fact]
    public void ReadsTheUpstreamFileAsIs()
    {
        // The entry point for the real file: if a submodule bump changes the shape
        // of what gstreamer-sharp generates, this is where it shows up.
        var path = Path.Combine(AppContext.BaseDirectory, "upstream/ObjectManager.cs");
        Assert.True(File.Exists(path), $"missing '{path}'; see the None/CopyToOutputDirectory item in the test project");

        var (driver, _) = Run(new InMemoryAdditionalText(path, File.ReadAllText(path)));

        Assert.Empty(driver.GetRunResult().Diagnostics);

        var generated = Generated(driver);

        Assert.Contains("global::Gst.App.AppSink.GType", generated);
        Assert.Contains("global::Gst.Rtp.RTPBasePayload.GType", generated);
        Assert.Contains("global::Gst.RtspServer.RTSPServer.GType", generated);
    }

    private static string Generated(GeneratorDriver driver) =>
        driver.GetRunResult()
            .Results.Single()
            .GeneratedSources
            .Single(source => source.HintName == "ObjectManager.g.cs")
            .SourceText.ToString();

    private static (GeneratorDriver Driver, Compilation Output) Run(params AdditionalText[] additionalFiles)
    {
        var syntaxTree = CSharpSyntaxTree.ParseText("", cancellationToken: TestContext.Current.CancellationToken);

        var compilation = CSharpCompilation.Create(
            assemblyName: "Tests",
            syntaxTrees: [syntaxTree]);

        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            generators: [new ObjectManagerGenerator().AsSourceGenerator()],
            additionalTexts: additionalFiles);

        driver = driver.RunGeneratorsAndUpdateCompilation(
            compilation,
            out var outputCompilation,
            out _,
            TestContext.Current.CancellationToken);

        return (driver, outputCompilation);
    }

    private sealed class InMemoryAdditionalText(string path, string content) : AdditionalText
    {
        public override string Path { get; } = path;
        public override SourceText GetText(CancellationToken cancellationToken = default) =>
            SourceText.From(content);
    }
}
